// Builds idra-photo.mjs: the whole server in one file, so a fresh clone needs no npm install.
// Also writes THIRD_PARTY_NOTICES.md for every package bundled into that file.
import fs from 'node:fs';
import path from 'node:path';
import { build } from 'esbuild';

const banner = [
  '// Idra Photo single-file build. Generated by `npm run bundle` from src/. Do not edit by hand.',
  '// Bundled third-party packages and their licenses: see THIRD_PARTY_NOTICES.md.',
  "import { createRequire as __idraCreateRequire } from 'node:module';",
  'const require = __idraCreateRequire(import.meta.url);',
].join('\n');

const result = await build({
  entryPoints: ['src/cli.ts'],
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node22',
  outfile: 'idra-photo.mjs',
  legalComments: 'eof',
  logLevel: 'warning',
  metafile: true,
  banner: { js: banner },
});

// Collect the package root of every bundled input under node_modules.
const roots = new Set();
for (const input of Object.keys(result.metafile.inputs)) {
  const parts = input.split('/');
  const i = parts.lastIndexOf('node_modules');
  if (i < 0) continue;
  const scoped = parts[i + 1]?.startsWith('@');
  roots.add(parts.slice(0, i + (scoped ? 3 : 2)).join('/'));
}

const sections = [...roots]
  .map((root) => {
    const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
    const licenseFile = fs.readdirSync(root).find((f) => /^(licen[cs]e|copying)(\.|$)/i.test(f));
    const text = licenseFile ? fs.readFileSync(path.join(root, licenseFile), 'utf8').replace(/\r\n/g, '\n').trim() : `License: ${pkg.license ?? 'see package'} (no license file shipped)`;
    return { name: pkg.name, version: pkg.version, license: pkg.license ?? 'unknown', text };
  })
  .sort((a, b) => a.name.localeCompare(b.name));

const out = [
  '# Third-party notices',
  '',
  '`idra-photo.mjs` bundles the packages below. Each keeps its own license, reproduced here.',
  '',
  '| Package | Version | License |',
  '|---|---|---|',
  ...sections.map((s) => `| ${s.name} | ${s.version} | ${s.license} |`),
  '',
  ...sections.flatMap((s) => [`## ${s.name} ${s.version}`, '', '```', s.text, '```', '']),
].join('\n');
fs.writeFileSync('THIRD_PARTY_NOTICES.md', out);
console.log(`bundled ${sections.length} third-party packages: ${sections.map((s) => `${s.name} (${s.license})`).join(', ')}`);
